{
  "description": "Jev-powered setup diagnostics and allow-only review for Claude Code shell approval requests",
  "modules": ["../dist/claude-controls.js"],
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|fork",
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": ["${CLAUDE_PLUGIN_ROOT}/dist/claude-hook.js"],
            "timeout": 10
          }
        ]
      }
    ],
    "PermissionRequest": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": ["${CLAUDE_PLUGIN_ROOT}/dist/claude-hook.js"],
            "timeout": 10
          }
        ]
      }
    ]
  }
}
